"""Convert Ryze's published JSON articles into the site's Jekyll collection."""
import argparse
from datetime import datetime, timezone
from html import escape, unescape
from html.parser import HTMLParser
import json
from pathlib import Path
import re
from urllib.parse import urlsplit

MARKER = "# Generated by import_ryze.py. Edit the source JSON in blog/data instead."
ALLOWED = set("p h2 h3 h4 h5 h6 ul ol li a strong em b i blockquote br hr code pre table thead tbody tfoot tr th td figure figcaption img div span dl dt dd details summary sup sub".split())
BLOCKED = set("script style iframe object embed form svg math template".split())
VOID = {"br", "hr", "img"}


def safe_url(value, image=False):
    value = unescape(str(value)).strip()
    if not value or any(ord(c) < 32 for c in value):
        return ""
    if value.startswith("/") and not value.startswith("//"):
        return value
    if not image and value.startswith("#"):
        return value
    schemes = {"https"} if image else {"https", "http", "mailto", "tel"}
    return value if urlsplit(value).scheme.lower() in schemes else ""


class ArticleHTML(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts, self.text, self.blocked = [], [], []

    def handle_starttag(self, tag, attrs):
        if self.blocked:
            if tag == self.blocked[-1]:
                self.blocked.append(tag)
            return
        if tag in BLOCKED:
            self.blocked.append(tag)
            return
        if tag not in ALLOWED:
            return
        clean = {}
        for key, value in attrs:
            if value is None:
                continue
            if key == "title" or (tag == "img" and key == "alt"):
                clean[key] = value
            elif (tag == "a" and key == "href") or (tag == "img" and key == "src"):
                url = safe_url(value, image=tag == "img")
                if url:
                    clean[key] = url
            elif tag in {"td", "th"} and key in {"colspan", "rowspan"}:
                if value.isdigit() and 1 <= int(value) <= 100:
                    clean[key] = value
        if tag == "img":
            if "src" not in clean:
                return
            clean.setdefault("alt", "")
            clean.update(loading="lazy", decoding="async")
        if tag == "a" and clean.get("href", "").startswith(("http:", "https:")):
            clean["rel"] = "noopener noreferrer"
        attributes = "".join(f' {key}="{escape(value, quote=True)}"' for key, value in clean.items())
        self.parts.append(f"<{tag}{attributes}>")

    def handle_startendtag(self, tag, attrs):
        if tag not in BLOCKED:
            self.handle_starttag(tag, attrs)
            if tag not in VOID:
                self.handle_endtag(tag)

    def handle_endtag(self, tag):
        if self.blocked:
            if tag == self.blocked[-1]:
                self.blocked.pop()
        elif tag in ALLOWED and tag not in VOID:
            self.parts.append(f"</{tag}>")

    def handle_data(self, data):
        if not self.blocked:
            self.parts.append(escape(data))
            self.text.append(data)


def article_date(value):
    parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.isoformat()


def render_article(data, source, root):
    if not isinstance(data, dict):
        raise ValueError("Article must be a JSON object")
    if data.get("status") != "published":
        return None
    slug = data.get("slug", "")
    if not isinstance(slug, str) or not re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", slug) or len(slug) > 120:
        raise ValueError("Article slug must contain lowercase words separated by dashes")
    if source.stem != slug:
        raise ValueError("Article slug must match its JSON filename")
    if any((root / name).exists() for name in (slug, slug + ".html", slug + ".md")):
        raise ValueError(f"Article would replace an existing site route: {slug}")
    title = str(data.get("title") or "").strip()
    body = data.get("body_html")
    if not title or not isinstance(body, str) or not body.strip():
        raise ValueError("Published article needs a title and body_html")
    parser = ArticleHTML()
    parser.feed(body)
    parser.close()
    if not "".join(parser.text).strip():
        raise ValueError("Article has no readable body")
    # Exported text must never execute Liquid includes during the site build.
    body = "".join(parser.parts).replace("{{", "&#123;{").replace("{%", "&#123;%")
    date = article_date(data.get("published_at"))
    modified = article_date(data.get("updated_at") or data["published_at"])
    description = str(data.get("meta_description") or data.get("excerpt") or " ".join(parser.text)[:180]).strip()
    fields = {
        "layout": "post", "title": title,
        "seo_title": str(data.get("meta_title") or title),
        "description": description, "date": date, "last_modified": modified,
        "permalink": f"/{slug}/", "ryze_source": source.relative_to(root).as_posix(),
        "category": str(data.get("category") or "Real life"),
        "category_key": "lifestyle", "edit_type": "The edit", "cover_note": title,
        "read_time": f'{max(1, round(len(" ".join(parser.text).split()) / 220))} min read',
    }
    image = data.get("image")
    if isinstance(image, dict) and safe_url(image.get("url", ""), image=True):
        fields["image"] = safe_url(image["url"], image=True)
        fields["image_alt"] = str(image.get("alt") or title)
    frontmatter = "\n".join(f"{key}: {json.dumps(value, ensure_ascii=False)}" for key, value in fields.items())
    return f"---\n{MARKER}\n{frontmatter}\n---\n{body}\n"


def sync_articles(root):
    root = Path(root).resolve()
    source_dir, output_dir = root / "blog/data", root / "_edits"
    planned = {}
    # Validate the complete batch before modifying any pages.
    for source in sorted(source_dir.glob("*.json")):
        if source.is_symlink() or source.stat().st_size > 2_000_000:
            raise ValueError(f"Invalid article source: {source.name}")
        try:
            data = json.loads(source.read_text(encoding="utf-8"))
            rendered = render_article(data, source, root)
        except (ValueError, TypeError, KeyError) as exc:
            raise ValueError(f"{source.name}: {exc}") from exc
        if rendered is not None:
            output = output_dir / f"ryze-{data['slug']}.md"
            if output.exists() and MARKER not in output.read_text(encoding="utf-8"):
                raise ValueError(f"Refusing to overwrite a personal edit: {output.name}")
            planned[output] = rendered
    changed = 0
    output_dir.mkdir(exist_ok=True)
    for output, content in planned.items():
        if not output.exists() or output.read_text(encoding="utf-8") != content:
            output.write_text(content, encoding="utf-8")
            changed += 1
    for old in output_dir.glob("ryze-*.md"):
        if old not in planned and MARKER in old.read_text(encoding="utf-8"):
            old.unlink()
            changed += 1
    return len(planned), changed


if __name__ == "__main__":
    cli = argparse.ArgumentParser(description=__doc__)
    cli.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[2])
    count, changes = sync_articles(cli.parse_args().root)
    print(f"Ryze import: {count} published articles, {changes} changed pages.")
